import { test } from "node:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AutonomousAgent } from "../src/agent.js";
import { DEFAULT_CONTINUATION } from "../src/types.js";
import { startGateway, makeRepo } from "./helpers/fixtures.js";
process.env.HOME = fs.mkdtempSync(path.join(os.tmpdir(), "probe-home-"));
const lines = (p: string, n: number) => Array.from({ length: n }, (_, i) => `${p} line ${i + 1}`).join("\n") + "\n";
const cfg = (endpoint: string, workspace: string): any => ({ endpoint, model: "m", maxSteps: 30, temperature: 0, workspace, shell: "bash", approvalMode: "auto", fullAccess: true, continuation: { ...DEFAULT_CONTINUATION, stagnationSteps: 30, maxRecoveries: 2 } });
async function run(label: string, calls: any[]) {
  const repo = makeRepo({ "f.txt": lines("f", 10), "x.txt": "same\n" });
  let n = 0;
  const gw = await startGateway(() => { n++; return { kind: "tools", calls } as any; });
  const agent = new AutonomousAgent(cfg(gw.url, repo));
  (agent as any).ui = new Proxy({}, { get: () => () => {} });
  let ran = 0;
  const orig = (agent as any).dispatchToolCall.bind(agent);
  (agent as any).dispatchToolCall = async (...a: any[]) => { ran++; return orig(...a); };
  try {
    const turn: any = await agent.runTurn("Fix it.");
    const r: any = agent.getObjective()?.execution?.recovery;
    console.log(`PROBE ${label}: requests=${n} dispatched=${ran} execution=${turn.execution} stop=${turn.stopReason ?? turn.reason ?? ""} detail=${JSON.stringify(turn.stopDetail ?? turn.detail ?? "").slice(0, 200)} stage=${r?.stage} notes=${r?.notes} denials=${r?.denials}`);
  } finally { agent.shutdown(); await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
}
